<template><div class="zone-table"><table><thead><tr><th>Région / Ville</th><th>Zones / Quartier couverts</th><th>Réparateurs disponibles</th><th>Statut couverture</th><th>Actions en 1 clic</th></tr></thead><tbody><tr v-for="zone in zones" :key="zone.id"><td class="city"><span><b>{{zone.city}}</b><small>Région</small></span></td><td class="districts">{{zone.districts}}</td><td class="technicians"><b>{{zone.technicians}} techniciens</b></td><td><span :class="['status',zone.active?'on':'off']">● {{zone.active?'Active':'Inactive'}}</span></td><td class="actions"><button @click="$emit('edit',zone)">Modifier</button><button @click="$emit('delete',zone)">Supprimer</button></td></tr><tr v-if="!zones.length"><td colspan="5" class="empty">Aucune zone ne correspond à la recherche.</td></tr></tbody></table></div></template>
<script setup>defineProps({zones:{type:Array,required:true}});defineEmits(['edit','delete'])</script>
<style scoped>.zone-table{overflow:auto;border:1px solid #ddebfb;border-radius:9px}table{width:100%;min-width:1040px;border-collapse:collapse;background:#fff}th{text-align:left;text-transform:uppercase;padding:15px 16px;background:#edf6ff;color:#2558a8;font-size:11px}td{padding:15px 16px;border-bottom:1px solid #e4eef9;color:#315c9f;font-size:13px;height:88px}tbody tr:nth-child(even){background:#f0faf8}tbody tr:nth-child(odd){background:#fff}tr:last-child td{border-bottom:0}.city{color:#174b50}.city b{display:block;font-size:14px}.city small{display:block;width:max-content;margin-top:6px;padding:4px 9px;border-radius:12px;background:#e5f4f0;color:#087f70;font-size:10px}.districts{max-width:320px;line-height:1.5}.technicians{color:#5375a9}.status{display:inline-block;padding:8px 13px;border-radius:20px;font-size:12px}.on{background:#dcf8ee;color:#00a976}.off{background:#eaf1fa;color:#6480ad}.actions{display:flex;align-items:center;gap:10px;white-space:nowrap}.actions button{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;width:112px;height:46px;padding:10px 15px;border:1px solid #8cbdff;color:#087f70;background:#fff;border-radius:8px;font-size:12px;font-weight:700}.actions button:last-child{border-color:#ff94a7;color:#ff3554}.empty{text-align:center;color:#6682b1}</style>
